NATIVE_REFUSAL = "System UI ownership, exact controls, ambiguity refusal or flag restoration changed"


def _require(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


GATE_OBSERVATION_MARKERS = (
    "unavailableGate", "GateFailure", "GateProbe", "gateProbeTime", "gateFailureNodes",
    "gateFailureObservation", "withGateFailureObservation", "documentsUiGateFailureSchema",
)


def gate_observation_present(ui: str) -> bool:
    # Text-shape detection only; this predicate never admits a source/root or partial helper.
    return any(token in ui for token in GATE_OBSERVATION_MARKERS)


def gate_observation_preimage(ui: str) -> str:
    postimage = ui
    # Current admission requires exactly one complete NEW shape, never a missing/partial helper.
    for addition in GATE_FAILURE_ADDITIONS:
        _require(ui.count(addition) == 1, OBSERVATION_REFUSAL)
        ui = ui.replace(addition, "", 1)
    _require(ui.count(GATE_FAILURE_ERROR_AFTER) == 1, OBSERVATION_REFUSAL)
    ui = ui.replace(GATE_FAILURE_ERROR_AFTER, GATE_FAILURE_ERROR_BEFORE, 1)
    _require(not gate_observation_present(ui), OBSERVATION_REFUSAL)
    # The separately bounded diagnostic never loosens the original 20s loop, eligible selection,
    # actual click, six-parent barrier, strict ambiguity/bounds, or native action deadlines.
    _require(ui.count(ORIGINAL_FIND_SOURCE) == 1, NATIVE_REFUSAL)
    # Bind every complete authored role/body/closing and helper location, not independent markers.
    # Native anchor mutations retain their original refusal category before placement is checked.
    expected = ui
    for before, after in GATE_OBSERVATION_POSTIMAGE_DELTAS:
        _require(expected.count(before) == 1, NATIVE_REFUSAL)
        expected = expected.replace(before, after, 1)
    _require(expected == postimage, OBSERVATION_REFUSAL)
    return ui

