def gate_observation_postimage(ui: str) -> str:
    """Historical text bridge only; no receipt/runtime admission, repair, or native acceptance.

    Reapply exactly the authored diagnostic fragments after the original resource
    bridge. Inexact native scope/action/deadline text is never overwritten.
    """
    _require(isinstance(ui, str) and not gate_observation_present(ui), OBSERVATION_REFUSAL)
    original = ui
    for before, after in GATE_OBSERVATION_POSTIMAGE_DELTAS:
        _require(ui.count(before) == 1, OBSERVATION_REFUSAL)
        ui = ui.replace(before, after, 1)
    _require(gate_observation_preimage(ui) == original, OBSERVATION_REFUSAL)
    return ui


